from pathlib import Path
import json,html,math
from native import ROOT,OUT
from place import stage

def main():
 audit=json.load(open(OUT/'audit.json'));samples=json.load(open(OUT/'samples.json'));plans=json.load(open(OUT/'placements-r2.json'));initial=stage('initial','results');lower={**initial,**stage('search-lower-tracks','results'),**stage('holdout-lower-tracks','results')};after=stage('placed-r2','results');leaks=stage('final-leaks','results');data=[]
 for q,p,a in zip(samples,plans,audit['samples']):
  sid=q['sampleID'];keys=sorted(p['lowerIDs'],key=lambda k:(lower[k]['observedRail'],len(lower[k]['tracks']['cueBall'])))
  example=keys[0] if keys else None
  data.append(dict(**a,seed=q['seed'],B=q['candidate']['B'],blockers=p['blockers'],numbers=p['numbers'],aNumber=p['A'],group=p['obstacleGroup'],original=after[sid+'/reference'],alternative=lower[example] if example else None,blocked=after[example] if example else None,exampleID=example,leak=next((r for k,r in leaks.items() if k.startswith(sid+'/')),None)))
 (OUT/'atlas-data.json').write_text(json.dumps(data,ensure_ascii=False))
 template='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>K球障碍球小样</title>
<style>*{box-sizing:border-box}body{margin:0;background:#0d1a22;color:#e7eeee;font:16px system-ui,-apple-system,sans-serif}header{padding:28px 3vw 20px;max-width:1600px;margin:auto}h1{font-size:28px;margin:0 0 12px}p{line-height:1.7;margin:8px 0;color:#bfcdd3}strong{color:#fff}.filters{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}button,select{min-height:44px;border-radius:9px;border:1px solid #46606d;color:#e7eeee;background:#1b303c;padding:10px 15px;font:inherit;cursor:pointer}button.active{background:#28745c;border-color:#6cd3a5}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;padding:0 3vw 40px;max-width:1600px;margin:auto}.card{background:#152731;border:1px solid #2e4754;border-radius:14px;overflow:hidden}.head{padding:18px 20px 8px}.head h2{font-size:20px;margin:0 0 8px}.badge{font-size:14px;color:#99e2b9}.bad{color:#ffb28c}.muted{color:#adc0cb}.tabs{display:flex;gap:6px;margin:10px 20px;flex-wrap:wrap}.tabs button{font-size:14px;padding:8px 12px}.table{padding:0 12px}svg{display:block;width:100%;height:auto}.metrics{padding:10px 20px 20px;line-height:1.8;font-size:15px}.legend{font-size:13px;padding:0 20px;color:#c2d0d6}.warning{border-left:3px solid #e9ae5b;padding-left:12px}a{color:#8ddac4}footer{padding:20px 3vw;color:#9db0ba}details{margin-top:8px;font-size:13px}summary{cursor:pointer;min-height:30px}@media(max-width:900px){.grid{grid-template-columns:1fr}h1{font-size:24px}}</style>
<header><h1>K球障碍球 · 8题可行性小样</h1><p><strong>保留原定打法，封住更少库数的捷径。</strong>两库限制一库；三库限制一、两库。库次沿用“入库前、出库后同属该库”。</p><p id="headline"></p><p class="warning">完成进A、K到B前，母球或A碰障碍球即失败。B碰后效果、母球落袋不限制。以下是有限搜索结果，不能证明所有其他打法都不存在；容错探针命中数不是真人成功率。</p><div class="filters"><button class="active" data-filter="all">全部 8题</button><button data-filter="sample-pass">本轮未再发现捷径</button><button data-filter="needs-more-search-or-placement">仍有捷径</button><button data-filter="not-needed-in-search">未找到需封堵的捷径</button></div></header><main class="grid" id="grid"></main><footer>物理事件与输入证据：<a href="audit.json">独立审计</a> · <a href="README.md">研究报告</a> · <a href="protocol.json">试验协议</a>。研究图册，未接入App，待用户看图和实打评估。</footer>
<script>const DATA=__DATA__;const colors=['','#e6ba22','#3267cd','#ce4438','#754ba3','#e68b2e','#26865c','#842f41','#161c20'];
const sx=x=>60+(x+1.27)*400,sz=z=>55+(z+.635)*400;
function line(points,color,width,dash='',opacity=1){if(!points?.length)return '';return `<polyline points="${points.map(p=>sx(p[1]).toFixed(2)+','+sz(p[2]).toFixed(2)).join(' ')}" fill="none" stroke="${color}" stroke-width="${width}" stroke-opacity="${opacity}" ${dash?'stroke-dasharray="'+dash+'"':''} stroke-linejoin="round"/>`}
function circle(x,z,r,fill,stroke='',w=1){return `<circle cx="${sx(x)}" cy="${sz(z)}" r="${r}" fill="${fill}" stroke="${stroke}" stroke-width="${w}"/>`}
function ball(p,num,role){const color=num===0?'#f6f7ed':colors[num>8?num-8:num],x=sx(p[0]),y=sz(p[1]),r=11.43;let b=circle(p[0],p[1],r+2,'none',role==='A'?'#66ceef':role==='B'?'#e5bd64':role==='obstacle'?'#ec9dce':'#c5d3da',2);b+=circle(p[0],p[1],r,num>8?'#f6f7ed':color);if(num>8)b+=`<path d="M ${x-10.25} ${y-5} L ${x+10.25} ${y-5} A ${r} ${r} 0 0 1 ${x+10.25} ${y+5} L ${x-10.25} ${y+5} A ${r} ${r} 0 0 1 ${x-10.25} ${y-5}" fill="${color}"/>`;if(num)b+=circle(p[0],p[1],6.7,'#fff');b+=`<text x="${x}" y="${y+3.7}" text-anchor="middle" font-size="10" font-weight="700" fill="#14232b">${num||'母'}</text>`;if(role==='A'||role==='B')b+=`<text x="${x+18}" y="${y-13}" font-size="15" fill="${role==='A'?'#85dff8':'#f0d091'}">${role}</text>`;return b}
function drawing(q,mode){let r=mode==='original'?q.original:mode==='alternative'?q.alternative:mode==='leak'?q.leak:q.blocked;let svg='<svg viewBox="0 0 1136 618" role="img" aria-label="'+q.id+'球桌轨迹"><rect x="35" y="30" width="1066" height="558" rx="25" fill="#544639"/><rect x="60" y="55" width="1016" height="508" fill="#20594f"/>';const pockets=[[-1.27,-.635],[1.27,-.635],[-1.27,.635],[1.27,.635],[0,-.635],[0,.635]];pockets.forEach((p,i)=>{svg+=circle(...p,18,'#0e1a21',i===q.pocket?'#67d6ed':'#918a73',i===q.pocket?4:2)});
if(r?.tracks){const ts=r.tracks;let t=r.events.find(e=>e.kind==='ballBall'&&e.balls.includes('cueBall')&&e.balls.includes('kTarget'))?.time??r.duration;if(mode==='blocked'){const first=r.events.find(e=>e.kind==='ballBall'&&e.balls.some(b=>b.startsWith('block_'))&&e.balls.some(b=>b==='cueBall'||b==='object'));if(first)t=Math.min(t,first.time)}svg+=line(ts.cueBall,'#bdc6c9',1.8,'',.40);svg+=line(ts.cueBall.filter(p=>p[0]<=t+1e-6),mode==='original'?'#fff2b5':'#ff9f70',3.4);svg+=line(ts.object,'#6fd5eb',2.5,'8 5');const c=ts.cueBall.filter(p=>p[0]<=t+1e-6);if(c.length>3){const i=Math.floor(c.length*.57),a=c[i],b=c[Math.min(i+3,c.length-1)],ang=Math.atan2(b[2]-a[2],b[1]-a[1])*180/Math.PI;svg+=`<path d="M -8 -5 L 7 0 L -8 5 Z" transform="translate(${sx(a[1])},${sz(a[2])}) rotate(${ang})" fill="${mode==='original'?'#fff2b5':'#ff9f70'}"/>`}}
if(mode!=='alternative')q.blockers.forEach((p,i)=>svg+=ball(p,q.numbers[i],'obstacle'));svg+=ball(q.seed.cue,0,'cue')+ball(q.seed.object,q.aNumber,'A')+ball(q.B,8,'B');return svg+'</svg>'}
function label(q){return q.status==='sample-pass'?'原打法保留 · 本轮复查未再发现捷径':q.status==='not-needed-in-search'?'本轮未找到低库解 · 暂不加球':'原打法保留 · 仍有漏网捷径'}
function card(q){const el=document.createElement('article');el.className='card';el.id=q.id;el.innerHTML=`<div class="head"><h2>${q.id} · ${q.rail===2?'两':'三'}库 · ${q.pocket>=4?'中袋':'角袋'} · ${q.axis==='inAngle'?'入库前K':'出库后K'}</h2><span class="badge ${q.status==='needs-more-search-or-placement'?'bad':q.status==='not-needed-in-search'?'muted':''}">${label(q)}</span></div><div class="tabs"><button class="active" data-mode="original">${q.obstacles?'加球后的原定路线':'原定路线（未加障碍）'}</button>${q.alternative?'<button data-mode="alternative">无障碍的低库解</button><button data-mode="blocked">加球后同一打法</button>':''}${q.leak?'<button data-mode="leak">仍可绕过的打法</button>':''}</div><div class="table">${drawing(q,'original')}</div><div class="legend">浅黄：原定母球路线　橙：低库打法　蓝虚线：A实际轨迹　灰：后续行程<br>${q.obstacles?'粉圈：障碍球（'+(q.group==='stripes'?'花色':'全色')+'）':'本题未加障碍球'}　A${q.aNumber} · B8</div><div class="metrics"><strong>${q.obstacles}颗障碍球</strong>　·　原打法120个容错探针：${q.toleranceBefore} → ${q.toleranceAfter}<br>已知低库解：${q.knownLower} → ${q.knownLowerRemaining}　·　最后独立512输入：${q.holdoutBefore} → ${q.holdoutAfter}<details><summary>查看来源与证据口径</summary>源球形 ${q.seed.layout}，路线 ${q.seed.route}。${q.exampleID?'对比示例 '+q.exampleID+'，实际观察库次 '+q.alternative.observedRail+'。':''}数字表示成功输入数，不代表互不相似的几何路线数。最后一批参数未用于摆球调整。</details></div>`;el.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{el.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));el.querySelector('.table').innerHTML=drawing(q,b.dataset.mode)});return el}
function render(filter){const grid=document.getElementById('grid');grid.replaceChildren(...DATA.filter(q=>filter==='all'||q.status===filter).map(card));document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter))}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>render(b.dataset.filter));document.getElementById('headline').textContent=`8题覆盖两库/三库、入库前/出库后、角袋/中袋。${DATA.filter(q=>q.status==='sample-pass').length}题本轮通过，${DATA.filter(q=>q.status==='needs-more-search-or-placement').length}题仍有捷径，${DATA.filter(q=>q.status==='not-needed-in-search').length}题暂未找到需封堵的捷径。`;render('all');</script></html>'''
 (OUT/'index.html').write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False)))
 print('atlas written',len(data))
if __name__=='__main__':main()
